import boto3
from datetime import datetime, timezone, timedelta

def cleanup_unattached_ebs(days=30, dry_run=True):
    ec2 = boto3.client("ec2", region_name="us-east-1")
    cutoff = datetime.now(timezone.utc) - timedelta(days=days)
